const { withAndroidManifest } = require('@expo/config-plugins');
const fs = require('node:fs/promises');
const path = require('node:path');

// Icons are generated by the dangerous mod before the manifest mod runs.
// Keep the supplied artwork inside the safe area of circular launcher masks.
module.exports = function withBrandIcon(config) {
  return withAndroidManifest(config, async result => {
    const dir = path.join(result.modRequest.platformProjectRoot, 'app/src/main/res/mipmap-anydpi-v26');
    for (const name of ['ic_launcher.xml', 'ic_launcher_round.xml']) {
      const file = path.join(dir, name);
      const xml = await fs.readFile(file, 'utf8');
      const padded = xml.replace(/<foreground\s+android:drawable="@mipmap\/ic_launcher_foreground"\s*\/>/,
        '<foreground><inset android:drawable="@mipmap/ic_launcher_foreground" android:inset="12%" /></foreground>');
      await fs.writeFile(file, padded);
    }
    return result;
  });
};
